const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const closingStatus=String(input.closing_status??input.close_status??"").toLowerCase();
const fundingStatus=String(input.funding_status??"").toLowerCase();
const titleStatus=String(input.title_status??"").toLowerCase();
const closeDate=String(input.actual_closing_date??input.closing_date??"").trim();
const gross=Number(input.gross_profit??input.assignment_fee??input.gross_assignment_profit);
const costs=Number(input.closing_costs??input.total_closing_costs??0);
const net=Number(input.net_profit??(Number.isFinite(gross)&&Number.isFinite(costs)?gross-costs:NaN));
const identityReady=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const closed=Boolean(["closed","funded","completed"].includes(closingStatus)||input.closed===true||input.verified_close===true);
const fundingReady=["funded","complete","completed","cleared"].includes(fundingStatus)||input.funding_verified===true;
const titleReady=["cleared","complete","completed"].includes(titleStatus)||input.title_verified===true;
const profitValid=Number.isFinite(gross)&&Number.isFinite(costs)&&Number.isFinite(net);
let status="blocked",nextWorkflow="WF-126",reason="";
if(blockers.length){reason="active closing blockers remain";}
else if(!identityReady){status="identity_incomplete";reason="deal/lead/property identity is incomplete";}
else if(!closed){status="close_not_verified";nextWorkflow="WF-307";reason="closing outcome is not yet verified";}
else if(!closeDate){status="closing_date_missing";nextWorkflow="WF-307";reason="actual closing date is missing";}
else if(!fundingReady||!titleReady){status="closing_evidence_incomplete";nextWorkflow="WF-307";reason="funding and/or title verification is incomplete";}
else if(!profitValid){status="profit_inputs_invalid";reason="gross profit, closing costs, or net profit inputs are invalid";}
else{status="verified_close";nextWorkflow="WF-309";reason="close, title, funding, and profit inputs are verified";}
const idempotencyKey=input.idempotency_key||`wf-308:${input.deal_id||"unknown"}:${closeDate||input.close_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-308",workflow_name:"Final Closing Outcome → Verified Close & Profit Reconciliation Controller",status,verified_close:{identity_ready:identityReady,close_verified:closed,actual_closing_date:closeDate||null,funding_verified:fundingReady,title_verified:titleReady,gross_profit:Number.isFinite(gross)?gross:null,closing_costs:Number.isFinite(costs)?costs:null,net_profit:Number.isFinite(net)?net:null,profit_valid:profitValid,blockers},next_workflow:nextWorkflow,human_review_required:status!=="verified_close",audit:{event_type:"verified_close_profit_reconciliation",idempotency_key:idempotencyKey,reason}}}];
